package org.pocketsurf.browser

import android.app.DownloadManager
import android.content.Intent
import android.net.Uri
import android.os.Looper
import android.view.*
import android.webkit.*
import android.widget.*
import org.junit.Test
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.*
import org.robolectric.annotation.Config
import org.robolectric.shadow.api.Shadow
import org.robolectric.shadows.ShadowDownloadManager.ShadowRequest
import java.time.Duration

@RunWith(RobolectricTestRunner::class)
@Config(sdk=[33],qualifiers="w960dp-h540dp-land-mdpi")
class HeuristicRegressionTest {
 @org.junit.Before fun skipFirstRunForBrowserFixture(){org.robolectric.RuntimeEnvironment.getApplication().getSharedPreferences("browser",0).edit().putBoolean("setup_complete",true).commit()}
 private fun all(v:View):List<View> = listOf(v)+if(v is ViewGroup)(0 until v.childCount).flatMap{all(v.getChildAt(it))}else emptyList()
 private fun views(a:BrowserActivity)=all(a.window.decorView)
 private fun text(a:BrowserActivity,s:String)=views(a).filterIsInstance<TextView>().firstOrNull{it.text.toString()==s}
 private fun settle(a:BrowserActivity,w:Int=960,h:Int=540){a.window.decorView.apply{measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));layout(0,0,w,h)};TestFrameClock.advance(Duration.ofMillis(if(views(a).any{it.contentDescription?.toString()?.endsWith(" popup")==true})360 else 16))}
 private fun start(url:String?=null)=Robolectric.buildActivity(BrowserActivity::class.java,Intent().apply{if(url!=null)data=Uri.parse(url)}).setup().visible().also{settle(it.get())}
 private fun key(a:BrowserActivity,k:Int){a.dispatchKeyEvent(KeyEvent(0,k));a.dispatchKeyEvent(KeyEvent(1,k));settle(a)}
 private fun click(a:BrowserActivity,s:String){if(s in listOf("Settings","History")){if(views(a).any{it.contentDescription=="Menu popup"})key(a,97);views(a).first{it.contentDescription==s}.performClick();settle(a);return};var v:View=views(a).firstOrNull{it.isShown&&it.hasOnClickListeners()&&it.contentDescription==s}?:text(a,s)?:views(a).firstOrNull{it.contentDescription?.toString()==s}?:error("Missing $s");while(!v.hasOnClickListeners())v=v.parent as View;v.performClick();settle(a)}
 private fun downloads(a:BrowserActivity){key(a,109);click(a,"Downloads")}
 private fun controls(a:BrowserActivity){key(a,109);click(a,"Settings");click(a,"Controller")}
 private fun request(a:BrowserActivity,id:Long):ShadowRequest=Shadow.extract(Shadows.shadowOf(a.getSystemService(DownloadManager::class.java)).getRequest(id))
 @Test fun completedDownloadCannotBeCancelledByStaleFocus(){val c=start();val a=c.get();val service=SurfDownloads(a);val item=service.start("https://example.com/a.pdf","test");val r=request(a,item.id);r.status=DownloadManager.STATUS_RUNNING;downloads(a);assertNotNull(text(a,"Cancel"));r.status=DownloadManager.STATUS_SUCCESSFUL;r.totalSize=1000;r.bytesSoFar=1000;TestFrameClock.advance(Duration.ofMillis(850));settle(a);assertNotNull(text(a,"Open file"));key(a,96);assertEquals(DownloadManager.STATUS_SUCCESSFUL,service.items().single().status);assertNotNull(Shadows.shadowOf(a.getSystemService(DownloadManager::class.java)).getRequest(item.id));assertFalse(service.cancel(item.id));c.pause().stop().destroy()}
 @Test fun offscreenCancelIsRevealedBeforeItCanRun(){val c=start();val a=c.get();val service=SurfDownloads(a);repeat(10){service.start("https://example.com/$it.pdf","test")};val first=service.items().first();downloads(a);val scroll=views(a).filterIsInstance<ScrollView>().single();scroll.scrollTo(0,2000);key(a,96);assertTrue(service.items().none{it.status==SurfDownloads.CANCELLED});assertTrue("Selection should be revealed",scroll.scrollY<500);c.pause().stop().destroy()}
 @Test fun themeChangeRetainsTheExistingBrowserEngine(){val c=start("https://example.com");val a=c.get();val v=views(a).filterIsInstance<WebView>().single();v.loadUrl("https://example.com/next");key(a,109);click(a,"Settings");click(a,"Appearance");click(a,"Light");assertNotNull(text(a,"Appearance"));key(a,97);key(a,97);assertSame(v,views(a).filterIsInstance<WebView>().single());assertEquals("https://example.com/next",v.url);c.pause().stop().destroy()}
 @Test fun galleryIgnoresGlobalSearchAndReturnsToOriginalTabForBothBackMethods(){for(touch in listOf(false,true)){RuntimeEnvironment.getApplication().getSharedPreferences("browser",0).edit().clear().putBoolean("setup_complete",true).commit();val c=start("https://original.test");val a=c.get();val original=views(a).filterIsInstance<WebView>().single();BrowserTestActions.openTabs(a);BrowserTestActions.newTab(a);views(a).first{it.contentDescription?.startsWith("Tab 1:")==true}.performClick();settle(a);BrowserTestActions.openTabs(a);key(a,105);val selected=a.window.decorView.findFocus();key(a,109);assertSame(selected,a.window.decorView.findFocus());assertTrue(views(a).none{it.contentDescription=="Menu popup"});assertTrue(views(a).none{it.contentDescription=="Go"&&it.isShown});assertNotNull(text(a,"Open tabs"));if(touch)views(a).first{it.contentDescription=="Back"&&it.isShown}.performClick()else key(a,97);settle(a);assertSame(original,views(a).filterIsInstance<WebView>().single());c.pause().stop().destroy()}}
 @Test fun recordingHasARealControllerCancel(){val c=start();val a=c.get();controls(a);click(a,"Confirm / open");click(a,"Record a button");assertNotNull(text(a,"Listening for a button…"));key(a,97);assertNotNull(text(a,"Controller"));assertEquals(96,ControllerBindings(a.getSharedPreferences("browser",0)).key(Control.CONFIRM));c.pause().stop().destroy()}
 @Test fun touchPickerCanAssignTheBackButton(){val c=start();val a=c.get();controls(a);click(a,"Confirm / open");click(a,"Choose from list");views(a).filterIsInstance<TextView>().first{it.text.toString()=="B"&&it.isShown&&it.parent is LinearLayout}.let{var target:View=it;while(!target.hasOnClickListeners())target=target.parent as View;target.performClick()};settle(a);assertNotNull(text(a,"Swap button assignments?"));click(a,"Swap buttons");val b=ControllerBindings(a.getSharedPreferences("browser",0));assertEquals(97,b.key(Control.CONFIRM));assertEquals(96,b.key(Control.BACK));c.pause().stop().destroy()}
 @Test fun pickerIncludesNonstandardCurrentlyAssignedButtons(){val c=start();val a=c.get();ControllerBindings(a.getSharedPreferences("browser",0)).assign(Control.BACK,188);controls(a);click(a,"Confirm / open");click(a,"Choose from list");assertNotNull(text(a,"Button 1"));c.pause().stop().destroy()}
 @Test fun deletionFocusMovesToOpenAndUndoDoesNotSelectClear(){val c=start();val a=c.get();val data=BrowserData(a.getSharedPreferences("browser",0));data.record("https://second.test","Second",time=1000);data.record("https://first.test","First",time=2000);key(a,109);click(a,"History");views(a).first{it.contentDescription=="Remove First"}.performClick();settle(a);assertNull(text(a,"First"));key(a,96);assertEquals("https://second.test",views(a).filterIsInstance<WebView>().single().url);key(a,109);click(a,"History");views(a).first{it.contentDescription=="Undo removal"}.performClick();settle(a);assertNotNull(text(a,"First"));key(a,96);assertTrue(views(a).any{it is WebView});assertNull(text(a,"Clear history?"));c.pause().stop().destroy()}
 @Test fun undoKeepsNewerBookmarks(){val c=start();val a=c.get();val d=BrowserData(a.getSharedPreferences("browser",0));d.record("https://saved.test","Old","bookmarks",1000);key(a,109);click(a,"Bookmarks");views(a).first{it.contentDescription=="Remove Old"}.performClick();d.record("https://fresh.test","Fresh","bookmarks",2000);click(a,"Undo removal");assertEquals(setOf("Old","Fresh"),d.entries("bookmarks").map{it.title}.toSet());c.pause().stop().destroy()}
 @Test fun searchLabelsFollowChosenEngineAndReloadIsDisabledAtHome(){val app=RuntimeEnvironment.getApplication();app.getSharedPreferences("browser",0).edit().putString("search","https://www.bing.com/search?q=").apply();val c=start();val a=c.get();assertTrue(views(a).filterIsInstance<EditText>().any{it.hint=="Search Bing or enter address"});assertFalse(views(a).first{it.contentDescription=="Reload page"}.isEnabled);BrowserTestActions.focusAddress(a);assertTrue(views(a).filterIsInstance<EditText>().any{it.contentDescription=="Address or Bing search"});assertEquals("android.widget.EditText",views(a).filterIsInstance<EditText>().first{it.contentDescription?.startsWith("Address or")==true}.createAccessibilityNodeInfo().className);c.pause().stop().destroy()}
 @Test fun loadProgressIsVisibleAndFailureHasPersistentRecovery(){val c=start("https://missing.test");val a=c.get();val v=views(a).filterIsInstance<WebView>().single();v.webChromeClient!!.onProgressChanged(v,37);assertTrue(views(a).any{it is PageLoadBar&&it.visibility==View.VISIBLE});assertFalse(views(a).filterIsInstance<TextView>().any{it.text.startsWith("Loading 37%")});val req=object:WebResourceRequest{override fun getUrl()=Uri.parse("https://missing.test");override fun isForMainFrame()=true;override fun isRedirect()=false;override fun hasGesture()=true;override fun getMethod()="GET";override fun getRequestHeaders()=emptyMap<String,String>()};val error=TestPageError(WebViewClient.ERROR_HOST_LOOKUP,"RAW_TECHNICAL_ERROR");v.webViewClient.onReceivedError(v,req,error);settle(a);assertNotNull(text(a,"Can't open this page"));assertNotNull(text(a,"Try again"));assertFalse(views(a).filterIsInstance<TextView>().any{it.text.contains("RAW_TECHNICAL_ERROR")});click(a,"Try again");assertSame(v,views(a).filterIsInstance<WebView>().single());c.pause().stop().destroy()}
 @Test fun editingAnErrorAddressReattachesTheEngineAndSameUrlReloads(){val c=start("https://missing.test");val a=c.get();val v=views(a).filterIsInstance<WebView>().single();val req=object:WebResourceRequest{override fun getUrl()=Uri.parse("https://missing.test");override fun isForMainFrame()=true;override fun isRedirect()=false;override fun hasGesture()=true;override fun getMethod()="GET";override fun getRequestHeaders()=emptyMap<String,String>()};v.webViewClient.onReceivedError(v,req,TestPageError(WebViewClient.ERROR_HOST_LOOKUP,"technical"));settle(a);click(a,"Edit address");views(a).filterIsInstance<EditText>().first{it.contentDescription?.startsWith("Address or")==true}.setText("https://working.test");click(a,"Go");assertSame(v,views(a).filterIsInstance<WebView>().single());assertNull(text(a,"Can't open this page"));assertEquals("https://working.test",v.url);BrowserTestActions.focusAddress(a);key(a,96);click(a,"Go");assertSame(v,views(a).filterIsInstance<WebView>().single());c.pause().stop().destroy()}
 @Test fun retryAfterAnErrorTabWasEvictedLoadsTheFailedUrl(){val c=start("https://failed.test");val a=c.get();val old=views(a).filterIsInstance<WebView>().single();old.loadUrl("https://older.test");val req=object:WebResourceRequest{override fun getUrl()=Uri.parse("https://failed.test");override fun isForMainFrame()=true;override fun isRedirect()=false;override fun hasGesture()=true;override fun getMethod()="GET";override fun getRequestHeaders()=emptyMap<String,String>()};old.webViewClient.onReceivedError(old,req,TestPageError(WebViewClient.ERROR_HOST_LOOKUP,"test"));repeat(4){c.newIntent(Intent(Intent.ACTION_VIEW,Uri.parse("https://other$it.test")));settle(a)};views(a).first{it.contentDescription?.startsWith("Tab 1:")==true}.performClick();settle(a);assertNotNull(text(a,"Can't open this page"));click(a,"Try again");assertEquals("https://failed.test",views(a).filterIsInstance<WebView>().single().url);c.pause().stop().destroy()}
 @Test fun helpIsReachableAndControlsHaveButtonSemantics(){val c=start();val a=c.get();key(a,109);val label=text(a,"Downloads")!!;var v:View=label;while(!v.hasOnClickListeners())v=v.parent as View;assertEquals("android.widget.Button",v.createAccessibilityNodeInfo().className);click(a,"Settings");click(a,"Help and controls");assertNotNull(text(a,"Browse with a controller"));assertNotNull(text(a,"Downloads and problems"));c.pause().stop().destroy()}
 @Test @Config(sdk=[33],qualifiers="w360dp-h720dp-port-mdpi") fun destructiveConfirmationFitsANarrowPhone(){val c=start();val a=c.get();key(a,109);click(a,"History");views(a).first{it.contentDescription=="Clear history"}.performClick();settle(a,360,720);assertNotNull(text(a,"Clear history"));for(name in listOf("Cancel","Clear history")){var v:View=text(a,name)!!;while(!v.hasOnClickListeners())v=v.parent as View;val xy=IntArray(2);v.getLocationOnScreen(xy);assertTrue("$name left",xy[0]>=0);assertTrue("$name right",xy[0]+v.width<=360)};c.pause().stop().destroy()}
}
